/**
 * Kaldi fbank + kaiser_best resample parity with torchaudio.
 *
 * Reads test/fixtures/kaldi_fbank_golden.json (generated by
 * test/generate_kaldi_fbank_golden.py with torchaudio) and checks the JS
 * front end used for the public zs-v1 base's CAM++ embeddings. torchaudio
 * computes in float32 and JS in float64, so values are compared with an
 * absolute tolerance instead of byte equality.
 *
 * Run: node --test src/wasm/openjtalk-web/test/js/test-kaldi-fbank-golden.js
 */

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join, resolve } from "node:path";

import { kaldiFbank, resampleKaiserBest, KALDI_FBANK_NUM_MEL_BINS } from "../../src/kaldi-fbank.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(__dirname, "..", "..", "..", "..", "..");
const FIXTURE = JSON.parse(
  readFileSync(join(REPO_ROOT, "test", "fixtures", "kaldi_fbank_golden.json"), "utf8")
);

// Mirrors test_signal() in the generator: DC offset plus sines below Nyquist,
// computed in float64 and stored as float32.
function testSignal(sampleRate, seconds) {
  const n = Math.round(sampleRate * seconds);
  const out = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    let x = FIXTURE.signal.dc_offset;
    for (const [amplitude, freq, phase] of FIXTURE.signal.partials) {
      if (freq < sampleRate / 2) {
        x += amplitude * Math.sin((2 * Math.PI * freq * i) / sampleRate + phase);
      }
    }
    out[i] = x;
  }
  return out;
}

// Tolerances cover float32 rounding in torchaudio, not algorithm changes:
// the largest fbank differences (~3e-3) sit in bins whose log energy is near
// -16, where float32 FFT cancellation dominates; a wrong window, mel scale or
// preemphasis moves whole frames by far more than 1e-2.
const RESAMPLE_MAX_ABS = 5e-5;
const FBANK_MAX_ABS = 1e-2;
const FBANK_MEAN_ABS = 1e-3;

function absDiffs(actual, expected) {
  assert.equal(actual.length, expected.length, "length");
  let max = 0;
  let sum = 0;
  for (let i = 0; i < actual.length; i++) {
    const d = Math.abs(actual[i] - expected[i]);
    max = Math.max(max, d);
    sum += d;
  }
  return { max, mean: sum / actual.length };
}

function assertFbankClose(feats, expected) {
  const { max, mean } = absDiffs(feats, expected);
  assert.ok(max < FBANK_MAX_ABS, `max abs diff ${max}`);
  assert.ok(mean < FBANK_MEAN_ABS, `mean abs diff ${mean}`);
}

describe("resampleKaiserBest matches torchaudio sinc_interp_kaiser", () => {
  for (const c of FIXTURE.resample_cases) {
    it(`${c.input_rate} Hz -> 16000 Hz`, () => {
      const out = resampleKaiserBest(testSignal(c.input_rate, c.seconds), c.input_rate, 16000);
      const { max } = absDiffs(out, c.output);
      assert.ok(max < RESAMPLE_MAX_ABS, `max abs diff ${max}`);
    });
  }

  it("returns the input unchanged at 16000 Hz", () => {
    const x = testSignal(16000, 0.01);
    assert.equal(resampleKaiserBest(x, 16000, 16000), x);
  });

  it("rejects invalid rates", () => {
    assert.throws(() => resampleKaiserBest(new Float32Array(10), 0, 16000), /sample rate/);
    assert.throws(() => resampleKaiserBest(new Float32Array(10), 44100.5, 16000), /sample rate/);
  });
});

describe("kaldiFbank matches torchaudio.compliance.kaldi.fbank", () => {
  it("16 kHz signal with DC offset", () => {
    const c = FIXTURE.fbank_case;
    const feats = kaldiFbank(testSignal(c.input_rate, c.seconds));
    assert.equal(feats.length / KALDI_FBANK_NUM_MEL_BINS, c.frames);
    assertFbankClose(feats, c.values);
  });

  it("48 kHz signal resampled first", () => {
    const c = FIXTURE.pipeline_case;
    const feats = kaldiFbank(
      resampleKaiserBest(testSignal(c.input_rate, c.seconds), c.input_rate, 16000)
    );
    assert.equal(feats.length / KALDI_FBANK_NUM_MEL_BINS, c.frames);
    assertFbankClose(feats, c.values);
  });

  it("returns no frames for input shorter than one 25 ms window", () => {
    assert.equal(kaldiFbank(new Float32Array(399)).length, 0);
    assert.equal(kaldiFbank(new Float32Array(400)).length, KALDI_FBANK_NUM_MEL_BINS);
  });
});
